            C++

    #include <iostream>
#include <stack>
using namespace std;

int main() {

    // creating a stack of integers
    stack<int> st; 

    st.push(1); 
    st.push(2); 
    st.push(3); 

    // Printing Current top element 
    cout << st.top() << " ";

    // removes the top element from the stack
    st.pop(); 

    // Printing Current top element 
    cout << st.top() << " ";

    // removes the top element from the stack
    st.pop(); 
}


